def get_prime_factors(n):
    """Get all prime factors of n with multiplicity"""
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def compute_gcd_list(nums):
    """Compute GCD of a list of numbers"""
    if not nums:
        return 0
    result = reduce(gcd, nums)
    return result

