    idx = 0
    n = int(lines[idx])
    s = int(lines[idx + 1])
    idx += 2

    buildings = []
    for i in range(n):
        v = int(lines[idx])
        c = int(lines[idx + 1])
        idx += 2
        buildings.append((v, c))

    # Sort by cost ascending, then by v descending
    buildings.sort(key=lambda x: (x[1], -x[0]))

    # Prune: for buildings with same price, keep only max v
    unique_buildings = []
    prev_c = -1
    for v, c in buildings:
        if c == prev_c:
            continue
        if not unique_buildings or unique_buildings[-1][1] != c:
            unique_buildings.append((v, c))
            prev_c = c

    # Also, keep only the best building per cost value (highest v)
    best = {}
    for v, c in buildings:
        if c not in best or v > best[c]:
            best[c] = v
    sorted_best = sorted(best.items(), key=lambda x: x[1], reverse=True)
    sorted_buildings = [ (v, c) for c, v in sorted_best ]

    def check(time: int) -> bool:
        if all(b[0] == 0 for b in sorted_buildings):
            return False  # no cookie generation possible

        current_cookies = 0

        # Simulate for each building to use as the "final" building
        for bv, bc in sorted_buildings:
            if current_cookies + bv * time >= s:
                return True

            if bc == 0:
                # Free building
                current_cookies = bv * time
                if current_cookies >= s:
                    return True

                remaining_time = time
                for cv, cc in sorted_buildings:
                    if cc == 0:
                        continue

                    # Buy time for each building
                    needed = cc - current_cookies
                    if needed <= 0:
                        continue

                    # Calculate how many of this building we can buy
                    count = needed // cc
                    if count == 0:
                        continue

                    buy_time = count * cc
                    if buy_time > remaining_time:
                        continue
                    if buy_time + (bv * remaining_time) >= s:
                        return True

                    current_cookies += bv * remaining_time - bv * (time - buy_time)
                    remaining_time -= buy_time
                    break
        return False

    # Binary search for minimum time
    min_time = 1
    max_time = s
    if min(buildings, key=lambda x: x[0])[0] > 0:
        max_time = s // min(buildings, key=lambda x: x[0])[0] + 2

    # If no free buildings, check manually
    has_free = any(c == 0 for v, c in sorted_buildings)
    if not has_free:
        # Use best building directly
        best_v = max(v for v, c in sorted_buildings)
        if best_v == 0:
            return str(s)
        max_time = (s + best_v - 1) // best_v
    else:
        min_time = 1
        best_v = sorted_buildings[-1][0] if sorted_buildings else 0
        if best_v > 0:
            max_time = (s + best_v - 1) // best_v
        else:
            max_time = s

    ans = max_time
    while min_time <= max_time:
        mid = (min_time + max_time) // 2
        if check(mid):
            ans = mid
            max_time = mid - 1
        else:
            min_time = mid + 1

    return str(ans) + '\n'

