def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n1, n2, nv = len(s1), len(s2), len(virus)

    if nv == 0:
        # No virus constraint - standard LCS
        dp = [[0] * (n2 + 1) for _ in range(n1 + 1)]
        for i in range(1, n1 + 1):
            for j in range(1, n2 + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        # Reconstruct
        i, j = n1, n2
        res = []
        while i > 0 and j > 0:
            if dp[i][j] == dp[i-1][j]:
                i -= 1
            elif dp[i][j] == dp[i][j-1]:
                j -= 1
            else:
                res.append(s1[i-1])
                i -= 1
                j -= 1
        return ''.join(reversed(res)) if res else '0'

    # KMP prefix function for virus
    pi = [0] * nv
    for i in range(1, nv):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def kmp_trans(state, char):
        # Returns the next KMP state after matching char
        while state > 0 and char != virus[state]:
            state = pi[state-1]
        if char == virus[state]:
            state += 1
        return min(state, nv)

    # DP: dp[i][j][k] = max LCS length using s1[:i], s2[:j], with KMP state k
    dp = [[[0] * (nv + 1) for _ in range(n2 + 1)] for _ in range(n1 + 1)]

    # To reconstruct solution
    parent = [[[None] * (nv + 1) for _ in range(n2 + 1)] for _ in range(n1 + 1)]

