                best_val = -1
                best_opp = None  # (prev_i, prev_j, prev_k)

                # Option 1: Skip s1 character
                if i > 0 and k <= nv:
                    val = dp[i-1][j][k]
                    if val > best_val:
                        best_val = val
                        best_opp = (i-1, j, k)

                # Option 2: Skip s2 character
                if j > 0 and k <= nv:
                    val = dp[i][j-1][k]
                    if val > best_val:
                        best_val = val
                        best_opp = (i, j-1, k)

                # Option 3: Match characters (if they match)
                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    new_state = kmp_trans(k, s1[i-1])
                    if new_state != nv and dp[i-1][j-1][k] + 1 > best_val:
                        best_val = dp[i-1][j-1][k] + 1
                        best_opp = (i-1, j-1, k, new_state)

                dp[i][j][k] = max(dp[i][j][k], best_val if best_val >= 0 else 0)

                # Store parent for reconstruction only if we made a meaningful choice
                if best_opp is not None or (i == 0 and j == 0):
                    parent[i][j][k] = best_opp
                    if isinstance(best_opp, tuple) and len(best_opp) >= 4:
                        dp[i][j][k] = best_val
                    else:
                        dp[i][j][k] = best_val

    # Special handling: initialize dp[0][0][0] = 0 explicitly
    dp[0][0][0] = 0

    # Find max over all valid KMP states in dp[n1][n2]
    max_len = 0
    for k in range(nv):
        if dp[n1][n2][k] > max_len:
            max_len = dp[n1][n2][k]

    if max_len == 0:
        # Check if any non-zero solution exists at all
        for k in range(nv + 1):
            for i in range(n1 + 1):
