                dp[k+1] = dp[k] + elem_cost

            # Try removing segment [k, j] 
            for j in range(k, min(n - 1, n)):  # At most n-1 removals (don't remove whole array)
                # After removing [k, j], we need to process remaining
                break  # Single removal, continue

        # Let's use a cleaner DP approach
        # State tracking: not in removal, in removal, after removal
        not_in_removal = [0] * (n + 1)
        in_removal = [INF] * (n + 1)
        after_removal = [INF] * (n + 1)

