import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    threshold = math.ceil(math.sqrt(n))

    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    level = [0] * (n + 1)
    on_stack = [False] * (n + 1)

    def dfs(u, p=0):
        visited[u] = True
        parent[u] = p
        level[u] = level[p] + 1 if p != 0 else 0
        on_stack[u] = True

        for v in adj[u]:
            if v != p:
                if visited[v]:
                    if on_stack[v] and level[v] < level[u]:
                        # Found back edge to ancestor
                        cycle = []
                        curr = v
                        cycle.append(v)
                        curr = u
                        while curr != v:
                            cycle.append(curr)
                            curr = parent[curr]
                        cycle.reverse()
                        return cycle
                elif not visited[v]:
                    parent[v] = u
                    level[v] = level[u] + 1
                    res = dfs(v, u)
                    if res:
                        return res

        on_stack[u] = False
        return None

    for i in range(1, n + 1):
        if not visited[i]:
            res = dfs(i)
            if res:
                cycle_len = len(res)
                if cycle_len >= threshold:
                    return "2\n{}\n{}".format(cycle_len, " ".join(map(str, res)))

    # Independent set
    result = []
    processed = [False] * (n + 1)

    for u in range(1, n + 1):
        if processed[u]:
            continue

        # Check if this vertex can be added to independent set
        can_add = True
        for v in adj[u]:
            if result and v in result:
                can_add = False
                break

        if can_add and u not in result:
            result.append(u)

        # Mark neighbors as processed
        for v in adj[u]:
            processed[v] = True

        for v in result:
            if v != u:
                for w in adj[v]:
                    processed[w] = True

    # Simple greedy independent set
    result = []
    for u in range(1, n + 1):
        can_add = True
        for v in result:
            if u in adj[v] or v in adj[u]:
                can_add = False
                break
        if can_add:
            result.append(u)

    return "1\n" + " ".join(map(str, result[:threshold]))


