def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"
    n, k = parse_ints(lines[0])

    def get_canonical(s):
        complement_s = ''.join('1' if c == '0' else '0' for c in s)
        reverse_s = s[-1::-1]
        complement_reverse = complement_s[-1::-1]
        candidates = [s, reverse_s, complement_s, complement_reverse]
        return min(candidates)

    reps = []
    seen = set()

    for i in range(2**n):
        s = bin(i)[2:].zfill(n)
        canon = get_canonical(s)
        if canon not in seen:
            seen.add(canon)
            reps.append(canon)

    reps.sort()

    if k <= len(reps):
        return reps[k - 1] + "\n"
    else:
        return "-1\n"

def parse_ints(s):
    import re
    matches = re.findall(r'\d+', s)
    return int(matches[0]), int(matches[1])

